package com.comfymobile.app;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.graphics.BitmapFactory;
import android.os.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.concurrent.*;
import okhttp3.*;

/** Synchronizes computer-owned batches independently of all activities. */
public final class NativeBatchService extends Service implements BatchEngine.Transport {
 private static final String CHANNEL="comfy_generation";private static final int NOTICE=42;private static final OkHttpClient CONTROL_CLIENT=new OkHttpClient.Builder().connectTimeout(6,TimeUnit.SECONDS).readTimeout(12,TimeUnit.SECONDS).build();
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();
 private final OkHttpClient client=new OkHttpClient.Builder().connectTimeout(12,TimeUnit.SECONDS).readTimeout(90,TimeUnit.SECONDS).writeTimeout(120,TimeUnit.SECONDS).pingInterval(20,TimeUnit.SECONDS).retryOnConnectionFailure(false).build();
 private BatchStore store;private BatchEngine engine;private PowerManager.WakeLock wake;private volatile boolean destroyed;private int lastStart;
 private final ConcurrentHashMap<String,WebSocket> sockets=new ConcurrentHashMap<>();
 @Override public void onCreate(){super.onCreate();try{store=BatchStore.open(getFilesDir());for(String mode:new String[]{"text","image","anime"}){JSONObject job=store.job(mode);if(job!=null&&!job.optBoolean("remoteOwned")){job.put("remotePreferred",true);store.save(job);}}String workflows;try(InputStream in=getAssets().open("workflows.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();copy(in,out);workflows=new String(out.toByteArray(),StandardCharsets.UTF_8);}engine=new BatchEngine(store,this,new JSONObject(workflows));NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel(CHANNEL,"ComfyUI 后台生成",NotificationManager.IMPORTANCE_LOW));startForeground(NOTICE,notification("正在接续生成任务"),ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,getPackageName()+":generation");wake.setReferenceCounted(false);wake.acquire();worker.scheduleWithFixedDelay(()->pump(),0,2,TimeUnit.SECONDS);}catch(Exception e){try{if(store!=null)for(String mode:new String[]{"text","image","anime"}){JSONObject job=store.job(mode);if(job!=null&&!BatchStore.terminal(job.optString("task"))){job.put("task","error").put("error","后台生成服务未能启动："+e.getMessage()).put("errorCode","background_service");store.save(job);}}}catch(Exception ignored){}stopSelf();}}
 @Override public int onStartCommand(Intent intent,int flags,int id){lastStart=id;return START_STICKY;}
 private Notification notification(String text){Intent open=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pending=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_menu_gallery).setContentTitle("Comfy Mobile · 后台生成").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(pending).setOngoing(true).setOnlyAlertOnce(true).setCategory(Notification.CATEGORY_PROGRESS).build();}
 private void pump(){if(destroyed)return;try{for(String mode:new String[]{"text","image","anime"}){JSONObject job=store.job(mode);if(job!=null&&!BatchStore.terminal(job.optString("task")))observe(job);engine.tick(mode);}StringBuilder text=new StringBuilder();for(String mode:new String[]{"text","image","anime"}){JSONObject j=store.job(mode);if(j!=null&&!BatchStore.terminal(j.optString("task"))){JSONObject b=j.getJSONObject("batch");if(text.length()>0)text.append("\n");text.append(mode.equals("text")?"文生图":mode.equals("anime")?"动漫":"图改图").append(" ").append(b.getInt("completed")).append("/").append(b.getInt("total")).append(" · ").append(j.optString("stage"));}else if(j!=null&&!j.optString("task").equals("paused")){for(int n=1;n<=2;n++){JSONObject input=j.optJSONObject("upload"+n);if(input!=null)new File(getFilesDir(),input.getString("path")).delete();}}}if(text.length()>0)getSystemService(NotificationManager.class).notify(NOTICE,notification(text.toString()));else{final int start=lastStart;new Handler(getMainLooper()).post(()->{try{if(!store.hasWork()&&start==lastStart){stopForeground(STOP_FOREGROUND_REMOVE);stopSelfResult(start);}}catch(Exception ignored){}});}}catch(Exception e){getSystemService(NotificationManager.class).notify(NOTICE,notification("任务记录暂时无法写入，请打开 App 检查存储空间"));}}
 private void observe(JSONObject job)throws Exception{String key=job.getString("server")+"|"+job.getString("clientId");if(sockets.containsKey(key))return;WebSocket ws=client.newWebSocket(request(job,"/ws?clientId="+java.net.URLEncoder.encode(job.getString("clientId")+"-background","UTF-8")).build(),new WebSocketListener(){@Override public void onMessage(WebSocket socket,String message){try{JSONObject event=new JSONObject(message),d=event.optJSONObject("data");if(d==null)return;String type=event.optString("type");if(type.equals("progress"))store.progress(d.optString("prompt_id"),d.optInt("value"),d.optInt("max"),"正在采样 · "+d.optInt("value")+" / "+d.optInt("max"));else if(type.equals("executing")&&!d.isNull("node"))store.progress(d.optString("prompt_id"),0,0,"正在执行节点 "+d.optString("node"));}catch(Exception ignored){}}@Override public void onFailure(WebSocket socket,Throwable error,Response response){sockets.remove(key,socket);}@Override public void onClosed(WebSocket socket,int code,String reason){sockets.remove(key,socket);}});sockets.put(key,ws);}
 private Request.Builder request(JSONObject j,String path)throws Exception{HttpUrl url=HttpUrl.parse(j.getString("server"));if(url==null)throw new Exception("服务器地址无效");Request.Builder request=new Request.Builder().url(j.getString("server")+path);String bearer=j.optString("bearer");if(!bearer.isEmpty())request.header("Authorization","Bearer "+bearer);return request;}
 private JSONObject response(Request request)throws Exception{try(Response r=client.newCall(request).execute()){String body=r.body()==null?"":r.body().string();if(!r.isSuccessful()){if(r.code()==404&&request.url().encodedPath().startsWith("/comfy-mobile/"))throw new Exception("电脑端批次托管扩展尚未加载，请重启 ComfyUI 后重试");String message="HTTP "+r.code()+" "+body.substring(0,Math.min(1600,body.length()));if(r.code()>=500)throw new IOException(message);throw new Exception(message);}return body.isEmpty()?new JSONObject():new JSONObject(body);}}
 public JSONObject get(JSONObject j,String path)throws Exception{return response(request(j,path).build());}
 public JSONObject post(JSONObject j,String path,JSONObject body)throws Exception{return response(request(j,path).post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"),body.toString())).build());}
 static void controlRemote(JSONObject job)throws Exception{if(job==null||!job.optBoolean("remoteOwned"))return;JSONObject batch=job.getJSONObject("batch");String command=batch.optBoolean("cancelRequested")?"cancel":batch.optBoolean("pauseRequested")?"pause":"resume";JSONObject body=new JSONObject().put("owner",job.getString("clientId")).put("version",batch.optInt("controlVersion")).put("command",command);Request.Builder request=new Request.Builder().url(job.getString("server")+"/comfy-mobile/batches/"+batch.getString("id")+"/control").post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"),body.toString()));if(!job.optString("bearer").isEmpty())request.header("Authorization","Bearer "+job.getString("bearer"));try(Response result=CONTROL_CLIENT.newCall(request.build()).execute()){if(!result.isSuccessful())throw new IOException("电脑端指令等待重试");}}
 public String upload(JSONObject j,JSONObject input)throws Exception{File file=new File(getFilesDir(),input.getString("path"));if(!file.isFile())throw new Exception("输入图片缓存不存在，请重新选择图片");RequestBody body=new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("image",input.getString("name"),RequestBody.create(MediaType.parse(input.optString("mime","image/png")),file)).addFormDataPart("type","input").addFormDataPart("overwrite","false").build();JSONObject result=response(request(j,"/upload/image").post(body).build());return result.optString("subfolder").isEmpty()?result.getString("name"):result.getString("subfolder")+"/"+result.getString("name");}
 public JSONObject cache(JSONObject j,String path,String id)throws Exception{File dir=new File(getFilesDir(),"images");dir.mkdirs();File image=new File(dir,id),temp=new File(dir,id+".part");if(!image.exists()){try(Response r=client.newCall(request(j,path).build()).execute()){if(!r.isSuccessful()||r.body()==null)throw new IOException("下载图片失败 HTTP "+r.code());try(InputStream in=r.body().byteStream();FileOutputStream out=new FileOutputStream(temp)){copy(in,out);out.getFD().sync();}Files.move(temp.toPath(),image.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{temp.delete();}}BitmapFactory.Options size=new BitmapFactory.Options();size.inJustDecodeBounds=true;BitmapFactory.decodeFile(image.getAbsolutePath(),size);if(size.outWidth<=0||size.outHeight<=0){image.delete();throw new IOException("下载的图片不完整，正在重试");}return new JSONObject().put("id",id).put("src","https://app.comfymobile.local/images/"+id).put("width",size.outWidth).put("height",size.outHeight);}
 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
 @Override public IBinder onBind(Intent intent){return null;}
 @Override public void onDestroy(){destroyed=true;worker.shutdownNow();for(WebSocket socket:sockets.values())socket.cancel();sockets.clear();client.dispatcher().cancelAll();if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
